IST = ZoneInfo('Asia/Kolkata')
SESSION_START = dtime(9, 15)
SESSION_END = dtime(15, 30)

def clean_bars(raw, now=None):
    """FYERS candles [epoch, open, high, low, close, volume] -> COMPLETED 5m IST bars."""
    now = now or datetime.now(IST)
    rows = []
    for bar in raw:
        if len(bar) < 6:
            continue
        ts = datetime.fromtimestamp(int(bar[0]), IST)
        if not SESSION_START <= ts.time() < SESSION_END:
            continue
        if ts + timedelta(minutes=5, seconds=5) > now:
            continue
        o, h, l, c, v = (float(x) for x in bar[1:6])
        if not all((math.isfinite(x) for x in (o, h, l, c, v))) or l > h or (not (l <= o <= h and l <= c <= h)):
            continue
        rows.append(dict(ts=ts, open=o, high=h, low=l, close=c, volume=v, day=ts.date()))
    df = pd.DataFrame(rows)
    if df.empty:
        return df
    return df.sort_values('ts').drop_duplicates('ts', keep='last').reset_index(drop=True)

def bracket_id(ts):
    return (ts.hour * 60 + ts.minute - (9 * 60 + 15)) // 30

def tpo_profile(day_df, row_size=5.0):
    if day_df.empty or row_size <= 0:
        return None
    groups = day_df.groupby(day_df.ts.map(bracket_id))
    counts = Counter()
    for _, g in groups:
        low, high = (float(g.low.min()), float(g.high.max()))
        a = math.floor((low + 1e-09) / row_size)
        b = math.floor((high + 1e-09) / row_size)
        for index in range(a, b + 1):
            counts[index] += 1
    if not counts:
        return None
    mid = (day_df.low.min() + day_df.high.max()) / 2
    poc = min(counts, key=lambda i: (-counts[i], abs(i * row_size - mid), i))
    left = right = poc
    included = counts[poc]
    target = math.ceil(sum(counts.values()) * 0.7)
    while included < target:
        li, ri = (left - 1, right + 1)
        lv, rv = (counts.get(li, 0), counts.get(ri, 0))
        if li < min(counts):
            lv = -1
        if ri > max(counts):
            rv = -1
        if lv < 0 and rv < 0:
            break
        if lv > rv or (lv == rv and abs(li * row_size - mid) <= abs(ri * row_size - mid)):
            left = li
            included += max(lv, 0)
        else:
            right = ri
            included += max(rv, 0)
    return dict(poc=round(poc * row_size, 3), vah=round((right + 1) * row_size, 3), val=round(left * row_size, 3), total_tpos=sum(counts.values()), brackets=len(groups), rows=sorted(((i * row_size, n) for i, n in counts.items())), convention='one-row outward, row interval [price,price+step)')

def confirmed_vrz(df, half_width=5.0):
    result = []
    if df.empty:
        return result
    for day, g in df.groupby('day'):
        brackets = []
        for idx, x in g.groupby(g.ts.map(bracket_id)):
            if len(x) != 6:
                continue
            start = min(x.ts)
            end = max(x.ts) + timedelta(minutes=5)
            brackets.append((idx, start, end, float(x.high.max()), float(x.low.min())))
        brackets.sort()
        for i in range(2, len(brackets) - 2):
            chunk = brackets[i - 2:i + 3]
            if any((chunk[j + 1][0] - chunk[j][0] != 1 for j in range(4))):
                continue
            cur = chunk[2]
            if all((cur[3] > x[3] for j, x in enumerate(chunk) if j != 2)):
                kind, px = ('HIGH', cur[3])
            elif all((cur[4] < x[4] for j, x in enumerate(chunk) if j != 2)):
                kind, px = ('LOW', cur[4])
            else:
                continue
            result.append(dict(kind=kind, lower=px - half_width, upper=px + half_width, center=px, formed_at=cur[2].isoformat(), available_at=chunk[4][2].isoformat(), day=str(day)))
    return result

def classify_bof(today, zones, now=None):
    events = []
    if today.empty:
        return events
    seen = set()
    for i in range(1, len(today)):
        prev, cur = (today.iloc[i - 1], today.iloc[i])
        if cur.ts - prev.ts != timedelta(minutes=5):
            continue
        for z in zones:
            if z['id'] in seen:
                continue
            if datetime.fromisoformat(z['available_at']) > prev.ts:
                continue
            lo, hi = (z['lower'], z['upper'])
            side = None
            if prev.close > hi and cur.close <= hi and (cur.close >= lo) and (i >= 2) and (today.iloc[i - 2].close <= hi):
                side = 'PE'
            if prev.close < lo and cur.close >= lo and (cur.close <= hi) and (i >= 2) and (today.iloc[i - 2].close >= lo):
                side = 'CE'
            if not side:
                continue
            strict = cur.close < prev.low if side == 'PE' else cur.close > prev.high
            events.append(dict(zone=z['id'], side=side, breakout_time=prev.ts.isoformat(), reclaim_time=cur.ts.isoformat(), strict=bool(strict), stop=float(max(prev.high, cur.high) if side == 'PE' else min(prev.low, cur.low)), status='RESEARCH_EVENT'))
            seen.add(z['id'])
    return events

def evaluate(raw, now=None, row_size=5.0):
    now = now or datetime.now(IST)
    df = clean_bars(raw, now)
    base = dict(status='INSUFFICIENT_DATA', decision='NO_TRADE', model='SHADOW_ONLY', reason='', previous_tpo=None, vrz_count=0, events=[], last_bar=None)
    if df.empty:
        base['reason'] = 'No completed valid 5-minute bars'
        return base
    base['last_bar'] = df.iloc[-1].ts.isoformat()
    if now - (df.iloc[-1].ts + timedelta(minutes=5)) > timedelta(minutes=15):
        base['reason'] = 'Stale 5-minute price bars'
        return base
    dates = sorted(set(df.day))
    today = now.date()
    completed = [d for d in dates if d < today]
    if today not in dates or not completed:
        base['reason'] = 'Current and previous completed sessions required'
        return base
    prev_date = completed[-1]
    prev = df[df.day == prev_date]
    expected = [datetime.combine(prev_date, SESSION_START, tzinfo=IST) + timedelta(minutes=5 * k) for k in range(75)]
    if len(prev) != 75 or list(prev.ts) != expected:
        base['reason'] = 'Previous session not complete at configured session hours'
        return base
    profile = tpo_profile(prev, row_size)
    base['previous_tpo'] = {k: v for k, v in profile.items() if k != 'rows'}
    cur = df[df.day == today]
    zones = [dict(id='PDVAH', lower=profile['vah'] - row_size, upper=profile['vah'], available_at=datetime.combine(today, SESSION_START, tzinfo=IST).isoformat()), dict(id='PDVAL', lower=profile['val'], upper=profile['val'] + row_size, available_at=datetime.combine(today, SESSION_START, tzinfo=IST).isoformat())]
    vrzs = confirmed_vrz(df[df.day <= today], half_width=row_size)
    for k, z in enumerate(vrzs):
        if datetime.fromisoformat(z['available_at']) <= now and z['kind'] in ('HIGH', 'LOW'):
            zones.append(dict(id=f'VRZ_{k}_{z['kind']}', lower=z['lower'], upper=z['upper'], available_at=z['available_at']))
    base['vrz_count'] = len(zones) - 2
    base['events'] = classify_bof(cur, zones)
    base['status'] = 'OK'
    base['decision'] = 'RESEARCH_ONLY'
    base['reason'] = 'Historical events shown; not a trade approval'
    return base
