    if not not_in_freeze:
        no_trade_reasons.append('OUTSIDE_TRADING_HOURS_OR_1515_FREEZE')
    bull_contradiction = fut_close < fut_vwap or fut_price_chg_3m < 0
    bear_contradiction = fut_close > fut_vwap or fut_price_chg_3m > 0
    final_verdict = 'NO TRADE'
    active_side = 'NONE'
    is_actionable = False
    if freshness_ok and not_in_freeze:
        if bull_pillar_oi and bull_pillar_fut and (not bull_contradiction) and (bear_pillars <= 1):
            final_verdict = 'BULL'
            active_side = 'BULL'
            is_actionable = True
            grade = 'STRONG ' if bull_pillars == 4 and has_2bar_sync else ''
            signal_banner = f'🟢 BULL — {grade}BUY {ACTIVE_INDEX} CE (Pillars {bull_pillars}/4 | Checks {bull_score}/9)'
        elif bear_pillar_oi and bear_pillar_fut and (not bear_contradiction) and (bull_pillars <= 1):
            final_verdict = 'BEAR'
            active_side = 'BEAR'
            is_actionable = True
            grade = 'STRONG ' if bear_pillars == 4 and has_2bar_sync else ''
            signal_banner = f'🔴 BEAR — {grade}BUY {ACTIVE_INDEX} PE (Pillars {bear_pillars}/4 | Checks {bear_score}/9)'
    if final_verdict == 'NO TRADE':
        if (b_c1 or b_c3) and bull_contradiction:
            no_trade_reasons.append('BULL_VETOED_BY_FUTURES')
        if (s_c1 or s_c3) and bear_contradiction:
            no_trade_reasons.append('BEAR_VETOED_BY_FUTURES')
        if not has_2bar_sync:
            no_trade_reasons.append('WARMUP_WAITING_2_BARS')
        if not no_trade_reasons:
            no_trade_reasons.append(f'INSUFFICIENT_ALIGNMENT (Bull {bull_pillars}/4 [{bull_score}/9] | Bear {bear_pillars}/4 [{bear_score}/9])')
        signal_banner = f'⚪ NO TRADE — {' | '.join(no_trade_reasons)}'
    if active_side == 'BULL':
        target_strike = bull_strike
        leg = ce_map.get(target_strike, ce_map[atm])
        opt_type_rec = 'CE'
    elif active_side == 'BEAR':
        target_strike = bear_strike
        leg = pe_map.get(target_strike, pe_map[atm])
        opt_type_rec = 'PE'
    else:
        target_strike = atm
        leg = ce_map.get(atm, {})
        opt_type_rec = 'NONE'
    g = leg.get('greeks', {'delta': 0.5, 'gamma': 0.001, 'theta': -15.0, 'vega': 5.0, 'iv': 14.0})
    entry_ask = float(leg.get('ask', 0) or leg.get('ltp', 100.0)) if opt_type_rec != 'NONE' else 0.0
    bid_p = float(leg.get('bid', 0) or entry_ask - 0.35) if opt_type_rec != 'NONE' else 0.0
    spread = round(max(entry_ask - bid_p, 0.25), 2) if opt_type_rec != 'NONE' else 0.0
    if is_actionable and spread > MAX_ALLOWED_SPREAD:
        final_verdict = 'NO TRADE'
        active_side = 'NONE'
        is_actionable = False
        opt_type_rec = 'NONE'
        no_trade_reasons.append(f'WIDE_BID_ASK_SPREAD_{spread}')
        signal_banner = f'⚪ NO TRADE — Wide Option Spread (₹{spread} > ₹{MAX_ALLOWED_SPREAD})'
    stop_dist = abs(spot - custom_stop_spot) if custom_stop_spot else DEFAULT_STOP_PTS
    gamma_cushion = 0.5 * float(g.get('gamma', 0.0)) * stop_dist ** 2
    loss_unit = max(abs(float(g.get('delta', 0.5))) * stop_dist - gamma_cushion + abs(float(g.get('theta', 0.0))) * 0.25 + spread, 2.0)
    opt_sl = round(max(entry_ask - loss_unit, 1.0), 2) if opt_type_rec != 'NONE' else 0.0
    loss_lot_rs = loss_unit * NIFTY_LOT_SIZE
    risk_budget = float(os.environ.get('RISK_PER_TRADE_RS', '7500.0'))
    lots = max(math.floor(risk_budget / max(loss_lot_rs, 1.0)), 1) if opt_type_rec != 'NONE' else 0
    est_risk_rs = round(lots * loss_lot_rs, 0) if opt_type_rec != 'NONE' else 0.0
    rec_contract_str = leg.get('symbol', 'NONE') if opt_type_rec != 'NONE' else 'NONE (NO TRADE)'
    trade_plan = {'final_verdict': final_verdict, 'decision_outcome': final_verdict, 'active_side': active_side, 'contract': rec_contract_str, 'strike': target_strike, 'type': opt_type_rec, 'expiry': chosen_exp['date'], 'dte': chosen_dte, 'entry_ask': entry_ask, 'spread_rs': spread, 'option_stop_price': opt_sl, 'spot_stop_pts': round(stop_dist, 1), 'lots': lots, 'qty': lots * NIFTY_LOT_SIZE, 'est_risk_rs': est_risk_rs, 'velocity_stop_mins': 45 if active_side == 'BULL' else 30}
    scorecard_rows = [{'Check': '1. Wall Gap Ratio + Price Conf', 'Bull_Live': f'PE/CE={pe_ce_ratio} (>={th['wall_gap_ratio_bull']}) & PxConf:{bull_price_conf_c1}', 'Bull_Status': 'PASS' if b_c1 else 'FAIL', 'Bear_Live': f'CE/PE={ce_pe_ratio} (>={th['wall_gap_ratio_bear']}) & PxConf:{bear_price_conf_c1}', 'Bear_Status': 'PASS' if s_c1 else 'FAIL'}, {'Check': '2. Opposing Cut (2x 3m Fixed K)', 'Bull_Live': f'{fixed_ce_wall_k}CE: {ce_cut_t1:.1f}%/{ce_cut_t2:.1f}% ({ce_cut_type})', 'Bull_Status': 'PASS' if b_c2 else 'FAIL', 'Bear_Live': f'{fixed_pe_wall_k}PE: {pe_cut_t1:.1f}%/{pe_cut_t2:.1f}% ({pe_cut_type})', 'Bear_Status': 'PASS' if s_c2 else 'FAIL'}, {'Check': '3. Supporting OI Speed (ToD Base)', 'Bull_Live': f'{pe_speed_mult}x (>={th['supporting_oi_speed']}x) | Corrob:{pe_writing_corroborated}', 'Bull_Status': 'PASS' if b_c3 else 'FAIL', 'Bear_Live': f'{ce_speed_mult}x (>={th['supporting_oi_speed']}x) | Corrob:{ce_writing_corroborated}', 'Bear_Status': 'PASS' if s_c3 else 'FAIL'}, {'Check': '4. 3m Churn (Lots Vol / |dOI|)', 'Bull_Live': f'{bull_churn} (<={th['max_churn_ratio']}, dOI={pe_doi_lots:.0f}L)', 'Bull_Status': 'PASS' if b_c4 else 'FAIL', 'Bear_Live': f'{bear_churn} (<={th['max_churn_ratio']}, dOI={ce_doi_lots:.0f}L)', 'Bear_Status': 'PASS' if s_c4 else 'FAIL'}, {'Check': '5. Fut vs FutVWAP + Wt Breadth*', 'Bull_Live': f'Fut>{fut_vwap} & WtBull={norm_bull_breadth:.0%}', 'Bull_Status': 'PASS' if b_c5 else 'FAIL', 'Bear_Live': f'Fut<{fut_vwap} & WtBear={norm_bear_breadth:.0%}', 'Bear_Status': 'PASS' if s_c5 else 'FAIL'}, {'Check': '6. Fut Quad (3m) + OptIV / VIX', 'Bull_Live': f'{fut_quad} | CE_dIV:{atm_ce_iv_chg:+.2f} | VIX:{vix_chp:+.1f}%', 'Bull_Status': 'PASS' if b_c6 else 'FAIL', 'Bear_Live': f'{fut_quad} | PE_dIV:{atm_pe_iv_chg:+.2f} | VIX:{vix_chp:+.1f}%', 'Bear_Status': 'PASS' if s_c6 else 'FAIL'}, {'Check': f'7. Fixed-K ({fixed_pivot_k}) 2x3m Flip', 'Bull_Live': f'Persist:{bull_oi_persist} | PxCross:{bull_price_persist} | V:{pe_vol_mult_k}x', 'Bull_Status': 'PASS' if b_c7 else 'FAIL', 'Bear_Live': f'Persist:{bear_oi_persist} | PxCross:{bear_price_persist} | V:{ce_vol_mult_k}x', 'Bear_Status': 'PASS' if s_c7 else 'FAIL'}, {'Check': f'8. Scenario γ-Flip ({gamma_flip})', 'Bull_Live': f'GEX:{net_gex_cr:+.0f}Cr/1% | VEX:{net_vex_cr:+.1f}Cr', 'Bull_Status': 'PASS' if b_c8 else 'FAIL', 'Bear_Live': f'GEX:{net_gex_cr:+.0f}Cr/1% | CEX:{net_cex_cr:+.1f}Cr', 'Bear_Status': 'PASS' if s_c8 else 'FAIL'}, {'Check': '9. Fixed Migration + Clock Filter', 'Bull_Live': f'{migration_str} | {clock_regime[:11]}', 'Bull_Status': 'PASS' if b_c9 else 'FAIL', 'Bear_Live': f'{migration_str} | {clock_regime[:11]}', 'Bear_Status': 'PASS' if s_c9 else 'FAIL'}]
    bull_flags_str = ' '.join([f'C{i + 1}:{('Y' if v else 'N')}' for i, v in enumerate(bull_list)])
    bear_flags_str = ' '.join([f'C{i + 1}:{('Y' if v else 'N')}' for i, v in enumerate(bear_list)])
    try:
        auction_history = fyers.history(data={'symbol': NIFTY_SPOT_SYM, 'resolution': '5', 'date_format': '1', 'range_from': (today_ist - timedelta(days=12)).isoformat(), 'range_to': today_ist.isoformat(), 'cont_flag': '1'})
        if auction_history.get('s') not in (None, 'ok') or not auction_history.get('candles'):
            raise ValueError('FYERS history returned no valid candles')
        auction_state = evaluate(auction_history['candles'], now=now_dt)
    except Exception as auction_error:
        auction_state = {'status': 'INSUFFICIENT_DATA', 'decision': 'NO_TRADE', 'reason': str(auction_error), 'events': [], 'previous_tpo': None}
    LATEST_STATE = {'status': 'OK', 'error': None, 'final_verdict': final_verdict, 'banner': signal_banner, 'decision_outcome': final_verdict, 'scorecard': scorecard_rows, 'trade_plan': trade_plan, 'auction_research': auction_state, 'layer2_audit': {'bull_pillars': f'{bull_pillars}/4', 'bear_pillars': f'{bear_pillars}/4', 'no_trade_reasons': no_trade_reasons, 'freshness_ok': freshness_ok, 'gex_units': f'{net_gex_cr:+.2f} ₹Cr / 1% Spot (OI-Signed Scenario)', 'vex_units': f'{net_vex_cr:+.2f} ₹Cr / 1% IV (OI-Signed Scenario)', 'cex_units': f'{net_cex_cr:+.2f} ₹Cr / Day (OI-Signed Scenario)'}, 'meta': {'ist_str': ist_str, 'fut_sym': fut_sym, 'data_mode': data_mode, 'spot': spot, 'gamma_flip': gamma_flip, 'fut_close': fut_close, 'fut_vwap': fut_vwap, 'vix': f'{vix_ltp} ({vix_chp}%)', 'straddle_idr': implied_daily_range, 'gex': f'{net_gex_cr:+.2f} Cr/1% ({gex_regime})', 'vex_cex': f'VEX {net_vex_cr:+.1f} Cr/IV | CEX {net_cex_cr:+.1f} Cr/d', 'put_wall': put_wall, 'call_wall': call_wall, 'atm_wall': wall_owner_now, 'seller_lead': atm_candidate_label, 'migration': migration_str, 'clock_regime': clock_regime, 'bull_breadth': f'{bull_cnt}/5 (Wt {norm_bull_breadth:.0%})', 'bear_breadth': f'{bear_cnt}/5 (Wt {norm_bear_breadth:.0%})', 'bull_score': f'{bull_score}/9 (Pillars {bull_pillars}/4)', 'bear_score': f'{bear_score}/9 (Pillars {bear_pillars}/4)', 'contract': rec_contract_str, 'dte': chosen_dte, 'ask': entry_ask, 'spread': spread, 'sl': opt_sl, 'lots': lots, 'qty': trade_plan['qty'], 'risk': f'{est_risk_rs:.0f}'}}
    if final_verdict == 'BULL':
        print('\n' + '🟢' * 36)
        print(f'🚀 FINAL VERDICT: [ BULL ] | {signal_banner}')
        print(f'🎯 BUY CE: {rec_contract_str} @ Ask ₹{entry_ask} | SL: ₹{opt_sl} | Lots: {lots} ({trade_plan['qty']}u) | Fut ({fut_sym}): {fut_close}')
        print('🟢' * 36 + '\n')
    elif final_verdict == 'BEAR':
        print('\n' + '🔴' * 36)
        print(f'🔻 FINAL VERDICT: [ BEAR ] | {signal_banner}')
        print(f'🎯 BUY PE: {rec_contract_str} @ Ask ₹{entry_ask} | SL: ₹{opt_sl} | Lots: {lots} ({trade_plan['qty']}u) | Fut ({fut_sym}): {fut_close}')
        print('🔴' * 36 + '\n')
    else:
        print(f'⚪ [{ist_str}] [ NO TRADE ] | {signal_banner} | Fut ({fut_sym}): {fut_close} vs VWAP: {fut_vwap} | {atm_candidate_label}')
    return LATEST_STATE
